-- ADR 0012, slice 2b: every tenant table's organization_id, and visitor_copies', references Better
-- Auth's auth.organization. Generated by drizzle-kit from src/db/schema.ts, with the backfill below
-- added by hand. No cascade: deleting an organization means deleting its rows first, inside its
-- own context, since Postgres runs cascades without Row Level Security (ADR 0005).
--
-- The backfill gives every organization that already has rows its own auth.organization row: the
-- demo, every visitor's copy, and any other organization a tenant table names (database tests leave
-- some behind locally). FORCE ROW LEVEL SECURITY hides tenant rows from the owner without a
-- context, so it is lifted for the backfill's reads only and restored in the same transaction;
-- the guard test checks every tenant table is forced again. Running it again changes nothing.
DO $$
DECLARE
  tenant text;
  tenants text[] := ARRAY['config', 'cost_config', 'categories', 'category_rates', 'people',
    'projects', 'project_pricing', 'scenarios', 'assignments', 'extra_costs', 'frozen_rates',
    'frozen_cost_config'];
  found_ids uuid[];
  ids uuid[] := ARRAY(
    SELECT '6d656d6f-0000-4000-8000-000000000001'::uuid
    UNION SELECT organization_id FROM public.visitor_copies
  );
BEGIN
  FOREACH tenant IN ARRAY tenants LOOP
    EXECUTE format('ALTER TABLE public.%I NO FORCE ROW LEVEL SECURITY', tenant);
    EXECUTE format('SELECT array_agg(DISTINCT organization_id) FROM public.%I', tenant)
      INTO found_ids;
    ids := ids || coalesce(found_ids, '{}');
    EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY', tenant);
  END LOOP;

  INSERT INTO auth.organization (id, name, slug)
    SELECT o.id,
      CASE
        WHEN o.id = '6d656d6f-0000-4000-8000-000000000001' THEN 'Squadio demo'
        WHEN EXISTS (SELECT 1 FROM public.visitor_copies v WHERE v.organization_id = o.id)
          THEN 'Visitor''s copy'
        ELSE 'Organization'
      END,
      CASE
        WHEN o.id = '6d656d6f-0000-4000-8000-000000000001' THEN 'demo'
        ELSE 'organization-' || o.id
      END
    FROM (SELECT DISTINCT unnest(ids) AS id) o
    ON CONFLICT DO NOTHING;
END
$$;
